import{_ as o,c as r,o as s,j as a,at as n,t as i}from"./chunks/framework.BlwsHpGA.js";const m=JSON.parse('{"title":"BE의 의미","description":"","frontmatter":{"layout":"doc","title":"BE의 의미","lastUpdated":true,"sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"blog/storyofbe.md","filePath":"blog/storyofbe.md"}'),l={name:"blog/storyofbe.md"};function p(t,e,d,b,c,g){return s(),r("div",null,[a("h1",null,i(t.$frontmatter.title),1),e[0]||(e[0]=n('<h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><div class="hero bold"><p><em>Be</em></p></div><div class="be flex between"><p>EN [biː] <strong>Verb</strong></p><span class="gray-txt-60"><p>originates from the Proto-Indo-European (PIE) root <em>bheue-</em>.</p></span></div><div class="be-segment border"><p><strong>-이다., 존재하다.</strong></p></div><p>영어 동사 <strong>be</strong>는 뜻은 <em>&#39;-이다., 존재하다&#39;</em> 로 의미적 본질은 &#39;존재(Existence)&#39;와 &#39;정체성(Identity)&#39;의 지속을 나타냅니다. 이를 디자인 시스템의 관점에서 보면 단순하게 화면을 스타일링 하는것을 넘어 프로덕트에 브랜드 정체성을 부여하고 존재감를 드러내도록 해주는 역활을 한다고 할 수 있습니다.</p><ul><li><p><strong>존재와 일관성 (Being Consistent):</strong> be는 대상이 변하지 않고 일관된 상태를 유지하는 것을 뜻합니다. 디자인 시스템 내에서 컬러, 타이포그래피, 컴포넌트는 프로덕트 전반에서 UI가 ‘일관성’을 갖도록 만드는 기준점 역할을 합니다.</p></li><li><p><strong>정체성의 확립 (Being an Identity):</strong> ‘~이다’라는 존재론적 의미는 브랜드의 정체성(Brand Identity)을 나타냅니다. 디자인 시스템은 브랜드가 사용자에게 어떤 느낌과 가치로 기억되고 인식될지(be) 규정하는 원칙의 집합입니다.</p></li><li><p><strong>단일한 진실의 원천 (Single Source of Truth):</strong> 철학적으로 be는 진리나 사실의 참됨을 내포합니다. 디자인 시스템은 기획자, 디자이너, 개발자 사이에서 무엇이 올바른 디자인 규격인지 가리키는 유일한 기준, 즉 ‘존재의 진실(Truth)/신뢰(Trust)’가 됩니다.</p></li></ul><p>그러나 사실은 ...</p><p>존재나 정체성 같은 심오한 의미를 갖는것도 중요하지만 be-가 포함된 수많은 긍정적인 단어들 때문에 선택하게 된것일 수도 있습니다. <em>Best, Better, Benefit, Beauty, Bewitch</em> 처럼.</p>',8))])}const _=o(l,[["render",p]]);export{m as __pageData,_ as default};
